import re, datetime
with open('/app/logs/auditd.log') as f:
    for line in f:
        m = re.search(r'audit\((\d+\.\d+):', line)
        if m:
            ts = float(m.group(1))
            dt = datetime.datetime.fromtimestamp(ts, datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
            print(f'{dt} | {line.strip()[:100]}')
""}

