import re, socket, struct

with open('/app/logs/auditd.log') as f:
    for line in f:
        if 'saddr=' in line:
            m = re.search(r'saddr=([0-9A-Fa-f]+)', line)
            if m:
                hex_data = bytes.fromhex(m.group(1))
                if len(hex_data) >= 8 and hex_data[:2] == b'\x02\x00':
                    port = struct.unpack('>H', hex_data[2:4])[0]
                    ip = socket.inet_ntoa(hex_data[4:8])
                    print(f'IP: {ip}, Port: {port} | Raw: {line.strip()[:80]}')
""}

